<script setup lang="ts">
import {nextTick,ref} from 'vue';
import {Archive,LoaderCircle,X} from 'lucide-vue-next';
import type {RepositoryLifecycleState} from '@oxen/shared';
import {post,request} from '../api';
const props=defineProps<{base:string;enabled:boolean}>(),emit=defineEmits<{removed:[]}>();
const open=ref(false),step=ref(1),state=ref<RepositoryLifecycleState>(),confirmation=ref(''),loading=ref(false),busy=ref(false),error=ref(''),input=ref<HTMLInputElement>();
async function begin(){if(!props.enabled)return;open.value=true;step.value=1;confirmation.value='';loading.value=true;error.value='';try{state.value=await request<RepositoryLifecycleState>(props.base+'/lifecycle');}catch(cause){error.value=(cause as Error).message;}finally{loading.value=false;}}
async function next(){step.value=2;await nextTick();input.value?.focus();}
async function remove(){if(!state.value||confirmation.value!==state.value.namespace+'/'+state.value.name)return;busy.value=true;error.value='';try{await post(props.base+'/lifecycle/remove',{confirmation:confirmation.value,expectedRevision:state.value.expectedRevision});open.value=false;emit('removed');}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
</script>
<template><section v-if="enabled" class="panel danger-zone"><header><h3>危险区域</h3><p>管理员可将项目移出当前工作空间，数据仍保留在本机 Oxen。</p></header><div><span><strong>移除项目</strong><small>移入本地回收站，保留 Oxen 版本、分支及未完成工作，可由管理员恢复。</small></span><button class="btn" @click="begin"><Archive :size="15"/>移除项目</button></div></section>
<div v-if="open" class="modal-backdrop" @click.self="!busy&&(open=false)"><section class="modal remove-dialog" role="alertdialog" aria-modal="true" aria-labelledby="remove-project-title" @keydown.esc="!busy&&(open=false)"><header><h3 id="remove-project-title">{{step===1?'核对移除影响':'确认移除项目'}}</h3><button class="icon-button" :disabled="busy" aria-label="关闭移除确认" @click="open=false"><X :size="18"/></button></header><p v-if="loading" role="status"><LoaderCircle class="spin" :size="18"/>读取项目最新状态…</p><template v-else-if="state"><p><strong>{{state.displayName}}</strong><code>{{state.namespace}}/{{state.name}}</code></p><template v-if="step===1"><p>项目将从 Web 工作空间及公开项目列表移除。项目页面、下载和编辑入口会暂停，管理员可以在本地回收站恢复。</p><p>保留 {{state.branchCount}} 个分支、{{state.workspaceCount}} 个工作区及 Oxen 版本。此操作不永久删除原始文件。</p><button class="btn btn-primary" @click="next">继续核对项目标识</button></template><form v-else @submit.prevent="remove"><label class="field">请输入完整项目标识 <code>{{state.namespace}}/{{state.name}}</code><input ref="input" v-model="confirmation" autocomplete="off" spellcheck="false" :disabled="busy" aria-label="确认移除的完整项目标识"/></label><p>确认将保留数据并移入本地回收站。若分支或工作区已改变，系统会要求重新核对。</p><footer><button type="button" class="btn" :disabled="busy" @click="open=false">取消</button><button class="btn remove-confirm" :disabled="busy||confirmation!==state.namespace+'/'+state.name"><LoaderCircle v-if="busy" class="spin" :size="15"/>移除项目（可恢复）</button></footer></form></template><p v-if="error" class="error-state" role="alert">{{error}}<button class="btn" :disabled="busy" @click="begin">重新核对最新状态</button></p></section></div></template>
<style scoped>.danger-zone{margin-top:30px;border-color:var(--danger);overflow:hidden}.danger-zone header{padding:20px 24px;border-bottom:1px solid var(--line)}.danger-zone h3{color:var(--danger);font-size:16px}.danger-zone p,.danger-zone small,.remove-dialog p{color:var(--muted);font-size:13px;line-height:1.8}.danger-zone>div{padding:22px 24px;display:flex;align-items:center;justify-content:space-between;gap:20px}.danger-zone small{display:block;margin-top:8px}.danger-zone .btn,.remove-confirm{color:var(--danger);border-color:var(--danger)}.remove-dialog{max-width:560px;padding:24px}.remove-dialog header,.remove-dialog footer{display:flex;align-items:center;justify-content:space-between;gap:15px}.remove-dialog p{margin:18px 0}.remove-dialog code{display:block;font:12px var(--font-mono,monospace);color:var(--text);overflow-wrap:anywhere}.remove-dialog h3{font-size:18px}.remove-dialog .field{margin:18px 0}.remove-dialog footer{justify-content:flex-end;margin-top:20px}@media(max-width:600px){.danger-zone>div{display:block;padding:18px}.danger-zone .btn{margin-top:16px}.remove-dialog{margin:12px;padding:20px}}</style>
